  MG({ name: 'Oracle', icon: '🧿', r: 0, cost: 2, desc: 'A prophecy about the future of the world.', fn: (c) => { const civs = alive(c.w); if (!civs.length) { toast(c, 'The oracle sees only silence.'); return; } const s = civs.slice().sort((a, b) => (b.pop * (b.era + 1)) - (a.pop * (a.era + 1)))[0]; const w = civs.slice().sort((a, b) => a.happiness - b.happiness)[0]; toast(c, `The oracle sees ${cname(s)} rising to dominate... while ${cname(w)} teeters on the edge.`); } });
