  MG({ name: 'Jinx', icon: '🐈‍⬛', r: 0, cost: 10, align: 'evil', desc: 'Bad luck: a random disaster hits the targeted civ.', fn: (c) => { if (!needCiv(c)) return; const bad = MB.ABILITIES.filter((a) => a.align === 'evil' && a.mode !== 'global' && a.cost <= 40 && !a.id.startsWith('paint')); const ab = U.pick(bad); L.castAbility(c.w, ab, c.civ.cx + 0.5, c.civ.cy + 0.5, ab.r, true); toast(c, `Jinx: ${ab.name}`); } });
  MG({ name: 'Luck', icon: '🍀', r: 0, cost: 10, align: 'good', desc: 'Good luck: a random blessing for the targeted civ.', fn: (c) => { if (!needCiv(c)) return; const good = MB.ABILITIES.filter((a) => a.align === 'good' && a.mode !== 'global' && a.cost <= 40 && a.cat !== 'Tools' && !a.id.startsWith('paint')); const ab = U.pick(good); L.castAbility(c.w, ab, c.civ.cx + 0.5, c.civ.cy + 0.5, ab.r, true); toast(c, `Luck: ${ab.name}`); } });
