  MG({ name: 'Levitate', icon: '🪽', r: 5, cost: 8, desc: 'Creatures float into the air (and drift away).', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind !== 'special') { e.vy -= 0.4; e.vx += U.rfloat(-0.2, 0.2); } }); } });
