  MG({ name: 'Frost Bolt', icon: '❄️', r: 2.5, cost: 6, mode: 'paint', rate: 120, desc: 'Freeze creatures and water.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind !== 'special') { e.frozen = 150; E.damage(c.w, e, 10, 'frost'); } }); c.w.forRadius(c.x, c.y, c.r * 0.6, (x, y, i) => { if (TILES[c.w.tiles[i]].water && c.w.tiles[i] !== T.DEEP) c.w.setIdx(i, T.FROZEN); }); fx.sparkle(c.x, c.y, '#a0e9ff', 6); } });
