  MG({ name: 'Banish Monsters', icon: '🚪', r: 10, cost: 15, align: 'good', desc: 'Monsters here are teleported far away.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'monster') { for (let k = 0; k < 10; k++) { const x = Math.random() * c.w.w, y = Math.random() * c.w.h; if (E.canStand(c.w, e, x, y) && c.w.owner[c.w.idx(x | 0, y | 0)] < 0) { e.x = x; e.y = y; e.target = 0; break; } } } }); fx.magic(c.x, c.y, c.r); } });
