  G({ name: 'Spawn 10 Tribes', icon: '🏕️', align: 'good', cost: 80, desc: 'Ten new tribes settle across the world.', fn: (c) => { let n = 0; for (let k = 0; k < 400 && n < 10; k++) { const x = U.rint(3, c.w.w - 4), y = U.rint(3, c.w.h - 4), i = c.w.idx(x, y); const t = c.w.tiles[i]; if (!TILES[t].build || c.w.owner[i] >= 0) continue; let ok = true; c.w.forRadius(x, y, 7, (xx, yy, j) => { if (c.w.owner[j] >= 0) ok = false; }); if (!ok) continue; if (C.found(c.w, x, y, { era: 0, pop: 12 })) n++; } toast(c, `${n} tribes founded.`); } });
