  G({ name: 'Great Migration', icon: '🦌', align: 'neutral', cost: 20, desc: 'All animals wander to new homes.', fn: (c) => { for (const e of c.w.entities) if (e.kind === 'animal') { e.home = null; e.tx = Math.random() * c.w.w; e.ty = Math.random() * c.w.h; e.hasTarget = true; e.timer = 2000; } } });
