  G({ name: 'Mirror World', icon: '🪞', align: 'neutral', cost: 50, desc: 'Flip the entire world left-to-right (civs and all).', fn: (c) => { const w = c.w; const W = w.w; const flip = (arr) => { for (let y = 0; y < w.h; y++) for (let x = 0; x < W / 2; x++) { const a = y * W + x, b = y * W + (W - 1 - x); const t = arr[a]; arr[a] = arr[b]; arr[b] = t; } }; flip(w.tiles); flip(w.height); flip(w.moist); flip(w.fire); flip(w.rad); flip(w.poll); flip(w.owner); const nb = new Map(); for (const b of w.buildings.values()) { b.x = W - 1 - b.x; b.i = b.y * W + b.x; nb.set(b.i, b); } w.buildings = nb; for (const civ of w.civs) { civ.cx = W - 1 - civ.cx; civ.tiles = new Set(); civ.buildings = new Set(); } for (let i = 0; i < w.n; i++) if (w.owner[i] >= 0 && w.civs[w.owner[i]]) w.civs[w.owner[i]].tiles.add(i); for (const b of w.buildings.values()) if (w.civs[b.civ]) w.civs[b.civ].buildings.add(b.i); for (const civ of w.civs) C.refreshTileArr(civ); for (const e of w.entities) { e.x = W - e.x; if (e.home) e.home.x = W - e.home.x; e.hasTarget = false; } w.burning = new Set(); w.lavaSet = new Set(); for (let i = 0; i < w.n; i++) { if (w.fire[i]) w.burning.add(i); if (w.tiles[i] === T.LAVA) w.lavaSet.add(i); } w.markAllDirty(); c.g.renderer.resetWorld(); toast(c, 'The world has been mirrored.'); } });

